input.new_string:
  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  await emit("member.removed", {
    ...actorEnvelope(actor),
    memberId: removed.id,
    userId: removed.userId,
  });

  // The event listener applies the same -1 when it is attached. Recounting
  // afterwards is what the billing page and plan checks read, and it stays
  // correct whether or not that listener ran.
  await usageRepo.recomputeUsage(input.orgId);

  return removed;
}

